/// Build a full SVG markup string for a named Fluent icon.
pub fn fluent_icon_svg(name: &str) -> String {
    format!(
        "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"{}\"/></svg>",
        fluent_icon_path(name)
    )
}
